-- 5006 🏋️ Exercises from the book "kindle-complete-guide-coaching-soccer-systems-tactics" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'kindle-complete-guide-coaching-soccer-systems-tactics');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Narrow grid game via end-line targets', 'small_sided_game', 'opposed', 'in_possession', 133, 134, 'Generic Activity: Penetration (Diagram 309)', NULL, 'Encourage forward, penetrating passing by making a pass to a target player a condition of scoring.', 'Long, narrow grid with a goal and keeper at each end and two target players standing on each end line beside the goal; team X v team O inside.', 'A team must first find one of the two targets on the end line it attacks before it is allowed to score; play then continues to goal. Examples: pass and follow for a return, or a third-man lay-off to a runner.', 'No goal counts until a target has received the ball; keepers may not pass to the targets.', NULL, 'Work the ball to a player who is facing forward with time; play forward instead of square whenever possible; sprint to support each forward pass.', 'two teams + 2 GK + 4 targets', NULL, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 10),
  ('6v4 uneven possession game', 'possession', 'overload', 'in_possession', 134, 134, 'Generic Activity: Possession (Diagram 310)', NULL, 'Teach both sides of uneven numbers: the bigger team moves the ball quickly, the smaller team shields and escapes pressure.', '40-yard grid, six O players against four X players, no goals.', 'Both teams try to keep the ball. The O team spreads to use the whole grid with quick one/two-touch circulation; the X team keeps it in tight spaces while outnumbered.', 'O players two touches max; X players unlimited touches.', NULL, 'O''s: good support angles, use full width and length, don''t bunch towards the ball (freeze play to correct shape). X''s: shield and dribble out of trouble. Both: read pressure - when to hold, when to release first time.', '6v4', 10, 10, '40 yard grid', 36.6, 36.6, NULL, false, false, false, NULL, 20),
  ('1v1 to end goals, instant new attacker', 'transition', 'opposed', 'to_defend', 134, 135, 'Generic Activity: Pressure on Transition (Diagrams 311-312)', NULL, 'Build the reflex to close the ball down immediately after losing it.', 'Grid with a small cone goal in the middle of each end line; two teams of four, each player with a ball, lined up behind opposite end lines.', 'Starts as 1v1 in the grid, each attacking the far goal. Whenever the ball crosses an end line or goes out, a new player from the defending end dribbles straight in to attack while the player who just finished must defend at once; a defender who wins it and shoots stays in to defend.', 'Players waiting on the lines can''t interfere; new attacker goes immediately without a coach signal.', 'Add a keeper who rolls saves out to the next attacker; play 2v2 with two new attackers entering each time.', 'Speed of reaction on loss; no waiting.', '4v4 (played 1v1 or 2v2)', 8, 8, NULL, NULL, NULL, NULL, true, false, true, NULL, 30),
  ('Three-team game to target boxes', 'transition', 'opposed', 'to_defend', 135, 136, 'Generic Activity: Pressing in Defense (Diagram 313)', NULL, 'Apply immediate pressure after losing the ball or scoring to stop the forward pass.', 'Grid about 25 yards wide by 35-40 long with a 2 x 5 yard target box at each end holding two players of the resting third team; spare balls behind each box.', '4v4: each team scores a point by passing into the box it attacks; the target player who catches it immediately serves to the other team, who then attack the opposite box. All restarts are a serve from a target player.', 'No throw-ins; target players stay in their box and catch passes. Resting team swaps in for the losing team after 5-10 minutes.', 'Four teams (two playing, two resting in the boxes); play 3v3, 4v4 or 5v5.', 'Speed of closing down on transition; press frontally to block the penetrating pass, force backwards or square passes, press everywhere to win it.', '3 teams of 4 (4v4 + 2 targets each end)', 12, 15, '25 x 35-40 yards', 34.3, 22.9, 10.0, false, false, true, NULL, 40),
  ('3v3 one-way: cover the presser', 'defending', 'opposed', 'out_of_possession', 137, 138, 'Generic Activity: Cover in Defense (Diagrams 314-315)', NULL, 'Teach small groups to cover the pressing defender with good angles and communication.', 'Grid 30-40 yards wide by 20-30 deep; groups of three O defenders queue on one end line, groups of three X attackers on the other.', 'An O group passes to an X group and steps out to defend; the X''s try to dribble the ball under control over the defenders'' line AB. When the ball goes out or O wins it, the next groups go.', 'O stays defending throughout for repetitions; reward them by switching roles after e.g. ten wins.', NULL, 'First defender presses, central one covers behind, far one tucks in behind him; on a square pass the far defender intercepts if he can, otherwise presses and waits for the others to slide across.', '3v3 with groups rotating', 12, NULL, '30-40 x 20-30 yards', 22.9, 32.0, NULL, false, false, true, NULL, 50),
  ('2 defenders trap attacker, corner goal', 'defending', 'overload', 'out_of_possession', 138, 139, 'Setting a Defensive Trap - Activity #1: 2v2 with one goal (Diagrams 316-317)', NULL, 'Channel the ball carrier away from goal, isolate and win it as a pressing/covering pair.', 'Grid 30 yards wide by 15-20 long with one 3-4 yard goal in a corner; attackers queue at one end, defenders at the corner by the goal. One attacking partner (X1) works only along the far line AB.', 'A defender passes to the attacker, who enters and tries to score in the corner goal while two defenders come out; he can use X1 on the line, who may pass back or shoot from the line. Rep ends on a win or ball out.', 'X1 may not enter the grid. Defenders rotate: covering defender becomes the presser next turn.', NULL, 'Curved approach to get between ball and goal; first defender steers him towards the dead side (line AC) and blocks the pass to X1; cover keeps distance/angle to block a shot; cover calls the tackle; pick the ''point of no return'' to commit.', '2 defenders v 1 attacker + 1 support', 6, NULL, '30 x 15-20 yards', 16.0, 27.4, NULL, true, false, true, NULL, 60),
  ('3v3 trap play to one corner goal', 'defending', 'opposed', 'out_of_possession', 139, 140, 'Setting a Defensive Trap - Activity #2: 3v3 with one goal (Diagrams 318-319)', NULL, 'Three defenders shepherd the ball towards the dead corner, create a 2v1 and win it while the third covers.', 'Grid 20 yards long by 30 wide, one corner goal; coach with balls on the side varies the starting point; groups of three X attackers and three O defenders queue on opposite lines.', 'Coach serves to the three X''s, who attack the corner goal; the three O''s come out together to close and steer play towards line AC, then pounce.', 'Keep the same group defending for many reps before swapping.', NULL, 'Immediate pressure as attackers pass to punish a poor touch; short calls on who presses and who covers; force 2v1 and close the ball while the third covers and blocks the shot.', '3v3 with groups rotating', 12, NULL, '20 x 30 yards', 18.3, 27.4, NULL, true, false, true, NULL, 70),
  ('5v5/6v6 with corner-offset goals', 'small_sided_game', 'opposed', 'out_of_possession', 140, 140, 'Setting a Defensive Trap - Activity #3: 5v5 or 6v6 with two goals (Diagram 320)', NULL, 'Transfer channelling and trapping into a normal game.', 'Larger grid with a goal at each end, each offset to a corner.', 'Regular game; when defending, teams try to push the ball into the dead-end corner away from their goal, isolate the carrier and swarm him.', NULL, NULL, 'Isolate the ball carrier with no way out.', '5v5 or 6v6', 10, 12, NULL, NULL, NULL, NULL, true, false, true, NULL, 80),
  ('Wide game, two corner goals each', 'small_sided_game', 'opposed', 'in_possession', 140, 141, 'Generic Activity: Switching the Point of Attack (Diagrams 321-322)', NULL, 'Switch play to the less defended side.', 'Wide, short rectangle with four small goals, one in each corner; each team attacks the two on one end and defends the other two.', 'Free play; if the near goal is crowded, switch to score in the far one.', NULL, NULL, 'Shape: don''t bunch on one side; keep a safe support player behind the ball as the outlet for the switch.', '4v4 to 8v8', 8, 16, NULL, NULL, NULL, NULL, true, false, true, NULL, 90),
  ('Left back builds out from GK throw', 'phase_of_play', 'opposed', 'in_possession', 142, 143, 'Functional Activity: Wide defender Playing Out of the Back (Diagrams 323-324)', NULL, 'Train the wide defender to start attacks from the keeper''s distribution.', 'Defensive half of the pitch; keeper, central defender, wide defender D1, three midfielders and two forwards against a marking black team; a black forward 6 optional.', 'Every rep starts with the keeper throwing to D1; the team must bring the ball under control into the other half. If black wins it, they play it back to the keeper and it restarts.', 'Reset to the start positions after success or ball out.', 'Start without forward 6 so D1 has time; then add 6 to press D1 once the keeper throws (D1 can then also go back to the keeper or across to the centre-back).', 'D1''s first touch, choice of pass (wide mid, forward''s feet, second forward''s run, midfielders), quality of delivery, and his movement after passing (step up or overlap).', 'team + opposition (about 9v6)', NULL, NULL, 'half pitch', NULL, NULL, NULL, false, true, true, NULL, 100),
  ('Back three play out, 11v6', 'phase_of_play', 'overload', 'in_possession', 143, 146, 'Functional Activity: The Back 3 Playing Out of the Defense (Diagrams 325-328)', NULL, 'Train the three defenders of a 3-5-2 to open up and build attacks from the back.', 'Half pitch plus; full team of 11 in a compact defensive shape against six opponents (two forwards, two midfielders, two defenders); coach with balls near halfway.', 'Coach plays a long ball behind the defence; once the keeper or sweeper collects, the team spreads (wide defenders wide and high, sweeper and holding mid staggered, midfield just below halfway, forwards stretch) and works it into the middle third to a faced-up midfielder, then over halfway. If the six win it they attack the goal.', 'Midfielders on the team of 11 two touches max; rep ends when the ball crosses halfway under control.', NULL, 'Defenders get wide quickly but keep a safe angle for the keeper; open body shape; sideways-on stance for sweeper/holding mid; quality first touch forward; early clear communication; switch via others or keeper if forward pass not on.', '11v6', 17, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Two back fours switch play', 'passing_unopposed', 'unopposed', 'in_possession', 146, 150, 'Functional Activity: Switching Play Using The Back Four (Diagrams 329-334)', NULL, 'Teach back lines the bowl shape to switch play in possession and the compact slide without it.', 'Middle third; a server in the centre circle with balls; two back fours, one in each half about 15 yards from halfway, flat and close together.', 'Server plays softly to a defender; that line drops into a bowl and passes across the line while the other line slides across flat and compact. The ball is then hit long to the other line and roles reverse.', 'Control then pass (two touches); passes in front of the feet.', 'Add a midfielder to each line to link, interchange and dribble up; then add two forwards (one per line) who press or check for the ball; the line without the ball marks the checking forward.', 'Angles and distances in the line; crisp, quick passing rhythm; occasionally skip a centre-back; quick transitions between attacking and defensive shapes; midfielders keep the ball moving in the same direction, forward''s lay-off goes to the opposite line.', '8 + server (up to 12)', 9, 13, 'middle third', NULL, NULL, NULL, false, false, false, NULL, 120),
  ('Centre-backs mark a target forward', 'defending', 'opposed', 'out_of_possession', 150, 155, 'Zonal Defending With 4-4-2 - Activity #1: Teaching Central Defenders to Mark the Target Player (Diagrams 335-340)', NULL, 'Build the centre-back partnership: sharing the marking of a target man, holding the line, stepping up and covering.', 'Defensive half; two centre-backs start about 5 yards outside their box with target player 5 against them; feeders 2 and 4 wide on halfway, 3 in the centre circle, 1 about 20 yards behind halfway; balls by the circle.', '3 starts each rep; attackers pass at game speed (1-2 touches) and feed 5 (ground, lofted, driven), who must lay it back. Centre-backs may only intercept passes to 5; they win it and play to 1 or clear it, then reload.', '5 cannot turn at first; 3 stays in the circle; 2 and 4 stay put; 1 moves side to side.', 'Add a keeper, let 5 turn and attack goal and 3 support from behind (assistant calls offside); then add a second forward so the pair switch between marking and covering and decide when to let a runner go offside.', 'Push up together on a back pass and hold the line about 10 yards from halfway; stay within 40 yards of the ball; communicate the hand-over; mark on the shoulder within touching distance; ''sandwich'' the forward (one tight, one behind); free defender drops behind on a pass to 5; follow a checking forward tightly.', '2 defenders v 5 attackers (later + GK, + second forward)', 7, 9, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Back four as a zonal unit', 'defending', 'opposed', 'out_of_possession', 155, 165, 'Zonal Defending With 4-4-2 - Activity #2: Teaching the Back Four to work as a Unit (Diagrams 341-354)', NULL, 'Back four moves up, down and across as one unit and passes forwards on to each other.', 'Defensive half; keeper and four defenders on a line about 5 yards outside the box against two forwards (5, 6) and wide players 2 and 4; 3 (coach or a central mid) in the centre circle with balls, 1 about 20 yards behind halfway.', '3 starts by passing to any attacker; if the defenders or keeper win it they play to 3 or 1 and push up together; reload after ball out. Stage one: attackers only receive and return to 3 so the coach can freeze and show positions for each ball location; stage two: forwards make lateral, crossing and checking runs; stage three: attackers go to goal, 3 can dribble through.', '3 may support but not run ahead of the ball; attackers restricted early on.', 'Add attacking mid 7 marked by holding mid M1; then build to 16 players: keeper, back four, M1, M2, M3 v two forwards, four mids and three back players with coach as 1 (starts attacks and is the counter outlet).', 'Stay narrow with no big gaps; mark inside shoulder; on a pass into a forward, cover drops behind (deeper for aerial balls); wide defender closes the wide player; ''sandwich'' cover between neighbours; hand runners on; track checking forwards; immediate pressure on the ball overrides marking; drop off with no pressure on the ball, hold flat and tight when there is; keep wide defenders in line for offside.', '5 defenders (incl GK) v 6 attackers, up to 16 players', 11, 16, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Strikers apply first pressure on build-up', 'defending', 'opposed', 'out_of_possession', 165, 167, 'Activity #3: Teaching The Forwards To Apply First Pressure', NULL, 'Teach the two strikers when and how to press opposing defenders building from the back, squeezing play to one flank.', 'Attacking third and middle third of a full pitch, both sides in 4-4-2 shape: coached team has 2 forwards, 2 midfielders and 3 defenders; opponents have a keeper, back four, a holding midfielder, two wide midfielders and one forward. Forwards start central while the keeper has the ball.', 'Keeper always starts by serving to one of his defenders; the build-up team tries to play out and get into the other half. Near forward closes the receiver on an angle that blocks the switch, the other forward cuts off the pass back across the line, and the back players pounce on passes down the line. If the defending team wins it they give it back to the keeper and everyone resets.', 'Reset from the keeper after a successful penetration, a regain or the ball going out.', 'Add transition: the pressing team may attack the goal when they win the ball.', 'Close the ball quickly and stay on your feet; force rushed passes; keep the ball on one side away from the unmarked far players; second forward watches the centre-backs and blocks the outlet into vacated midfield; drop back centrally when ball goes back to keeper; agree the trigger line, about 10-20 yards past halfway.', '16 (7 v 8 + keeper)', 16, 16, 'two thirds of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('3-5-2 midfield runs into attacking third', 'positional_game', 'opposed', 'in_possession', 167, 169, 'Functional Activity: Attacking From Middle Third in 3-5-2', NULL, 'Teach the five midfielders in a 3-5-2 to make penetrating runs with the ball into the attacking third.', 'Pitch split into thirds with dotted lines. Coached team: 2 defenders at the back line of the middle third, 5 midfielders in their match shape (two holding, two wide, one attacking) and 2 forwards at the top of the middle third; 5 opposing midfielders match up against them.', 'Each attack starts with a serve from a defender. The team scores by getting a midfielder into the attacking third with the ball under control, by dribble or pass; defenders may chase into that third until control is gained, then play restarts from the back. Coach can walk the team through passing patterns ending in a final pass into the attacking third.', 'Only midfielders may enter the attacking third. Defenders support and switch play but cannot enter the middle third. Forwards are unmarked, two-touch, cannot turn or run into the attacking third. Offside applies (line at highest forward or cones). Defending team scores by winning the ball and playing it back to the defenders.', NULL, 'Keep balanced width and depth in midfield; wide midfielders hug the touchlines so one long switch can stretch the opponent; draw them to one side, play back, then diagonal switch; holding midfielders keep adjusting to offer back passes.', '14 (9 v 5)', 14, 14, 'middle and attacking thirds', NULL, NULL, NULL, false, false, true, NULL, 160),
  ('Functional scrimmage in game shape', 'small_sided_game', 'opposed', 'in_possession', 169, 170, 'Functional Activity: The scrimmage', NULL, 'Use a small-sided scrimmage with players in their real positions to work a team topic, e.g. wide defenders overlapping.', '7v7 on part of the pitch with a keeper in each goal; each team lines up 4-2 to recreate a back four with two forwards against it.', 'Play a normal scrimmage while the coach focuses on the movement of the wide players. Starting back line can be kept together on one team with alternates on the other and rotated.', NULL, 'With 16 players use a 4-1-2 shape (better than 4-2-1 so four defenders face two forwards). Even five-a-side can be functional with a 2-2-1 shape.', 'Players placed in game-like positions so the scrimmage mirrors the team''s shape.', '7v7 incl. keepers', 14, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Pattern to cross, sprint back recovery', 'combination', 'unopposed', 'in_possession', 170, 171, 'Diagram 359A', NULL, 'Combine a position-specific passing move, crossing and finishing with match-specific fitness.', 'Six players start around the middle third facing a goal with a keeper.', 'Players run a set passing pattern out to the wing that ends in a cross with runners attacking the box, then everyone sprints back to the starting spots to mimic the transition to defending.', 'Work-to-rest can be set for interval effect, e.g. about 10 s of work with 20 s rest for 1:2.', NULL, 'Execute at game speed; finish the cross; sprint back immediately.', '6 + keeper', 7, 7, NULL, NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Shadow play in attacking third', 'combination', 'passive', 'in_possession', 186, 190, 'Shadow Play in Attacking Third', NULL, 'Rehearse midfield ball circulation and then combination plays to break into the box and finish from crosses.', 'Four midfielders in a half-moon just outside the attacking third, one forward, three passive defenders in front of the penalty area.', 'Midfielders circulate side to side (M1-M2-M3-M4, wide man dribbles down the line, spins and plays back the other way) while the forward shifts across to support and defenders shadow the ball without tackling. Then the forward joins in, checking away and back to receive and lay off first time.', 'Inside midfielders two touches; defenders passive and jockey only.', 'Add a keeper and rehearse combinations ending in a cross with set box runs: wall pass, third-man run, overlap. Add a second forward and a through ball option. Let defenders tackle, then add a fourth defender and a holding midfielder pressing the midfield.', 'Crisp passes across the receiver''s front foot; everything at match speed, defenders too; midfield slides across to stay compact with the far wide man tucking in; talk and use cue runs/shouts; watch run timing, pass pace and spacing; possession-then-sudden-penetration rhythm decided by players.', '5 attackers + 3 defenders (+ keeper later)', 8, 12, 'attacking half', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Full-field 4-4-2 shadow pattern end to end', 'combination', 'passive', 'in_possession', 190, 192, 'Full Field Shadow Play (Diagram 389)', NULL, 'Rehearse building from the back through the thirds to a shot with many repetitions and minimal reload time.', 'Full pitch, keeper at each end, 16 players: a 4-4-2 team with redundant positions removed, plus passive shadow markers.', 'Keeper throws out to start a set pattern that finishes with a shot at the other end while defenders mark passively. After the shot that keeper starts the sequence back the other way and the roles swap so the other team shadows.', 'Defenders passive.', 'Opponent-specific version: in 3-5-2, left defender plays to left midfielder and back, then a long diagonal to the far wide midfielder for an early cross behind the defence; reload and repeat from the right side (Diagram 391). Sequences may also start in the middle or defending third, or new players can take the starting spots while the first group jogs back.', 'Plan start positions, ball supply and reloading to maximise repetitions; many stoppages early to fix timing, then less coaching; repeat regularly all season so it becomes ingrained.', '16', 16, 22, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Flank groups of four shadow attack', 'combination', 'unopposed', 'in_possession', 191, 192, 'Diagram 390', NULL, 'Rehearse flank penetration patterns at high tempo with little wasted time.', 'Central defender with balls in the middle of own half; a group of four on each flank; keeper in goal at the far end.', 'Central defender feeds one flank; that group of four plays its combination down the wing and finishes. While they jog back, the defender feeds the other flank group.', NULL, 'Swap in different flank penetration patterns.', NULL, '9 + keeper', 10, 10, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('2v2 combinations at the edge of the box', 'finishing', 'opposed', 'in_possession', 200, 203, 'Activity #1: Combination Plays on the Edge of the Penalty Area', NULL, 'Forwards and attacking mids learn to combine quickly against two defenders to create and finish chances from the edge of the area.', 'Channel as wide as the six-yard box, running from the goal line to about 10 yards beyond the penalty area, keeper in goal. Defenders queue on one side with all the balls, attackers queue at the top of the channel and on the other side; coach stands by the channel as a target.', 'First defender plays the ball to the first attacker and steps up to challenge; at once a second attacker and second defender enter, making it 2v2. Attackers use wall passes, crossovers, overlaps, through balls or a dribble to get in behind and score; defenders try to win it and pass to the coach or clear it out of the channel.', 'Points: defenders score 1 for winning the ball and finding the coach or for a ball out/keeper save; attackers 1 for a shot on target, 5 for a goal, and may counter-press before the ball reaches the coach. Offside applies: first the penalty-area line, later the deeper defender.', 'Widen the channel by about 10 yards and play 2v3 with a sweeper; then 3v3 adding an attacking midfielder behind the two forwards.', 'First touch goes straight at goal to commit the defender; partner shakes his marker with a feint step and change of direction; right distance and angle between attackers; read the defenders to pick the option; use a partner''s run as a decoy; this is penetration, not keep-ball; shoot on sight, screen the keeper, follow in rebounds.', '2v2 + GK (rotating lines)', 9, NULL, 'six-yard-box width x to 10 yards outside the penalty area', 25.6, 16.8, NULL, true, true, true, NULL, 220),
  ('Forwards check, receive, turn and shoot', 'finishing', 'unopposed', 'in_possession', 204, 206, 'Activity #2: Forwards Receiving and Turning', NULL, 'Strikers learn to create space with checking runs, receive, turn and get a shot off quickly.', 'Half pitch, keeper in goal. Two midfielders wide in front of the box, one forward with a supply of balls at the halfway line, two forwards working around the edge of the area.', 'The feeding forward passes to a midfielder, who controls and plays to a working forward; the forward turns with his first touch and shoots with the second. Each forward gets two attempts (one from each side), then the next goes; after about 5 minutes the feeder swaps in.', 'Two-touch for midfielders (control, pass); forward turns with first touch, shoots with second outside the box or first time inside it.', 'Add a defender marking the forward tightly; the passing midfielder may now support behind for a lay-off and the forward can turn or lay off and spin in behind. Only the forward may shoot. Use the penalty-area line as a fixed offside line.', 'Move away first, then check into space; time the final run as the midfielder looks up; first touch away from the (imagined) defender, e.g. outside of the foot toward the D; inside the box shoot first time, low to the far post; scan the keeper before shooting; stand on the defender''s blind shoulder; watch work-to-rest ratio.', '3 forwards + 2 midfielders + GK (+1 defender in progression)', 6, 7, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Possession rhythm game with floaters', 'possession', 'overload', 'in_possession', 207, 210, 'Developing a Possession Rhythm (Diagrams 417-420)', NULL, 'Build a possession rhythm: stretch the field, support the ball, play the way you face, one and two touch, short-short-long switches, early communication.', 'Grid sized to the players (e.g. 30 x 30 yards). Version A: 6v6 inside with 2 neutrals inside. Version B: two teams inside with a third team as neutrals round the outside (6v6+6), or each team split half inside, half outside (4v4 in, 4+4 out).', 'Team in possession keeps the ball with help of the neutrals/outside players, aiming for a set number of consecutive passes to score; outside players act as pressure relief and switch the ball, inside players act as rebound walls. Rotate the neutral team for rest.', 'Optional conditions: one touch for floaters, or one touch for all but floaters; no pass back to the passer; every third pass long; only pass the way you face; outside players one touch, cannot play the same outside player twice or back to the same inside player; inside player who passes out swaps with the receiver.', 'Remove the numerical advantage once the rhythm is there and play equal numbers.', 'Get the ball out of congested areas quickly; last pass finds a free outside player with time; use playmakers as floaters.', '6v6+2, 6v6+6 or 4v4+4v4 outside', 14, 18, '30 x 30 yards (adjust to level)', 27.4, 27.4, NULL, false, false, false, NULL, 240)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'kindle-complete-guide-coaching-soccer-systems-tactics') b;
INSERT INTO schema_migrations (filename) VALUES ('5006-exercises-book-kindle-complete-guide-coaching-soccer-systems-tactics.sql') ON CONFLICT DO NOTHING;
COMMIT;
